syntax = "proto2";


package Game;
enum Command
{
    cmd_place_holder = 0;
    S2C_LoginError = 0x1005; //登录错误
    S2C_LoginSucc = 0x1007; //登录房间成功 通知自己
    S2C_LogoutSucc = 0x1008; //退出房间成功 通知自己
    S2C_ReconnSucc = 0x1009; //重连成功
    S2C_UserEnterRoom = 0x100D; //玩家进入房间 通知其他玩家
    S2C_UserQuitRoom = 0x100E; //玩家退出房间
    S2C_UserReadyStatus = 0x4001; //玩家准备状态
    S2C_UserAutoStatus = 0x4007; //玩家托管状态
    
    S2C_SystemError = 0x5000;
    S2C_GameStart = 0x5001; //游戏开始
    S2C_DingZhuang = 0x5003; //定庄
    S2C_DealCard = 0x5005; //拿牌
    S2C_SplitOptions = 0x5010; //通知分墩选项
    C2S_SplitCards = 0x5011; //玩家选择分墩
    S2C_SplitResult = 0x5012; //分墩结果
    S2C_CompareResult = 0x5013; //大小比较结果
    S2C_RoundFinish = 0x5014; //回合结束
    S2C_ExtendSettle = 0x5015; //打枪和全垒打
    S2C_Settle = 0x5016; //结算消息
    S2C_GameOver = 0x5017; //游戏结束
    S2C_StartCompare = 0x5018; //开始比牌
    S2C_StartGunShot = 0x5019; //开始打枪
};

// S2C_LoginError
message RspLoginError 
{
    optional uint32 errcode = 1;
};

message RoomInfo 
{
    optional uint32 level = 1;
    optional uint32 basechip = 2;
    optional uint32 deskfee = 3;
    optional uint32 total_game = 4;
};

message RoomUserInfo 
{
    optional uint32 uid = 1;
    optional uint32 seatid = 2;
    optional bool ready = 3;
    optional bool ai = 4; //是否托管
    optional uint64 money = 5;
    optional string userinfo = 6; //json格式
};

// S2C_LoginSucc
message RspLoginSuccess
{
    optional RoomInfo room_info = 1;
    optional RoomUserInfo self_info = 2;
    repeated RoomUserInfo others = 3;
};

// S2C_LogoutSucc
message RspLogoutSuccess 
{
    optional uint32 uid = 1; //退出玩家uid
};

// S2C_ReconnSucc
message RspReconnSuccess
{
    optional uint32 uid = 1; //自己uid
    optional uint32 optime = 2;
    optional uint32 banker_uid = 3;
    optional RoomInfo room_info = 4;  
    repeated RoomUserInfo user_info = 5;
    repeated RspSplitResult stack_data = 6; 
    repeated RspRoundFinish score_data = 7;
};

// S2C_UserEnterRoom
message RspUserEnterRoom 
{
    optional RoomUserInfo userinfo = 1;
};

// S2C_UserQuitRoom
message RspUserQuitRoom
{
    optional uint32 uid = 1;
};

// S2C_UserReadyStatus
message RspUserReadyStatus
{
    optional uint32 uid = 1;
    optional bool ready = 2; // 0-未准备 1-准备 
};

// S2C_UserAutoStatus
message RspUserAutoStatus
{
    optional uint32 uid = 1;
    optional bool ai = 2; //0-未托管 1-托管
};

/////////////////////////////////////////////////////////////////////////

//对局出现异常，对局会结束
message SystemError 
{
    optional uint32 errcode = 1;
    optional string reason = 2;
};

// S2C_GameStart
message RspGameStart
{
    optional uint32 param = 1;
}

//S2C_DingZhuang
message RspDingZhuang 
{
    optional uint32 banker_uid = 1;
};

//S2C_DealCard
message RspDealCard 
{
    optional uint32 uid = 1;
    optional uint32 num = 2;
    repeated uint32 cards = 3;
};

message CardStackData
{
    optional uint32 type = 1; //牌型
    repeated uint32 cards = 2; //牌
};

message SplitOptions 
{
    optional CardStackData first = 1;
    optional CardStackData second = 2;
    optional CardStackData third = 3;
    optional CardStackData special = 4;
};

// S2C_SplitOptions 分墩选项
message RspSplitOptions
{
    optional uint32 optime = 1; //操作时间
    optional uint32 uid = 2;
    repeated SplitOptions opts = 3; //所有可选的分墩选项
};

//C2S_SplitCards 
message ReqSplitCards 
{
    optional uint32 uid = 1;
    optional int32 select_idx = 2; //-1,自己分墩  大于等于0: 从RspSplitOptions的opts中选择
    optional SplitOptions select = 3; //玩家自己分墩
}

//S2C_SplitResult //分墩结果
message RspSplitResult
{
    optional uint32 uid = 1;
    optional SplitOptions select_opt = 2; //数据仅自己可见
    optional uint32 errcode = 3; //0-合法  非0-参考错误码
    optional bool is_special = 4; //特殊牌型标记
    optional bool done = 5; //分墩阶段重连用 标记是否已提交
};

//S2C_CompareResult
message RspCompareResult
{
    optional uint32 round = 1;  //第几堆牌比较
    optional uint32 uid = 2;    //当前亮牌玩家
    optional CardStackData cards = 5; //牌堆
};

//S2C_RoundFinish
message RspRoundFinish 
{
    optional uint32 round = 1;
    optional uint32 uid = 2; 
    optional int32 round_score = 3; //当前回合得分
}

message SettleItem 
{
    optional uint32 uid = 1;
    optional uint32 status = 2; //1-打枪玩家 2-被打枪玩家
    optional int64 score = 3; //积分或者 turnmoney
    optional int64 money = 4;
}

//S2C_ExtendSettle 打枪和全垒打
message RspExtendSettle 
{
    optional uint32 type = 1; //1-打枪 2-全垒打
    repeated SettleItem items = 3; 
}

// S2C_Settle 结算消息
message RspSettle 
{
    repeated SettleItem items = 1;
};

// S2C_GameOver
message RspGameOver 
{
    optional uint32 param = 1;
};

// S2C_StartCompare
message RspStartCompare
{
    optional uint32 param = 1;
}

message RspStartGunShot 
{
    optional uint32 param = 1;
}
